mapper.select:
select *
from seckill_coupon_claim_failure
where (
    status in ('RECONCILE_PENDING', 'DEAD_LETTERED', 'RECHECK_PENDING')
    and update_time <= #{readyBefore}
    and coalesce(next_reconcile_time, update_time) <= #{now}
) or (
    status = 'PROCESSING'
    and (
        processing_deadline <= #{now}
        or (processing_deadline is null and update_time <= #{leaseExpiredBefore})
    )
)
order by update_time asc, id asc
limit #{limit}

select *
from seckill_coupon_claim_failure
where (
    status = 'REPAIR_PENDING'
    and coalesce(next_reconcile_time, update_time) <= #{now}
) or (
    status = 'REPAIRING'
    and (
        processing_deadline <= #{now}
        or (processing_deadline is null and update_time <= #{legacyLeaseExpiredBefore})
    )
)
order by coalesce(next_reconcile_time, update_time) asc, id asc
limit #{limit}

select *
from seckill_coupon_claim_failure
where claim_id = #{claimId}
  and user_id = #{userId}
order by occurred_time desc, id desc
limit 1
